package com.gameaggregator.apikeyservice.infrastructure;import com.gameaggregator.apikeyservice.domain.ApiKey;import java.time.*;import org.slf4j.*;import org.springframework.data.redis.core.StringRedisTemplate;import org.springframework.stereotype.Component;@Component public class ApiKeyCache{static final Logger log=LoggerFactory.getLogger(ApiKeyCache.class);final StringRedisTemplate redis;public ApiKeyCache(StringRedisTemplate r){redis=r;}public void put(ApiKey k){try{String v="{\"apiKeyId\":\""+k.id+"\",\"tenantId\":\""+k.tenantId+"\",\"clientId\":\""+k.clientId+"\",\"environmentId\":\""+k.environmentId+"\",\"scopes\":"+k.scopesJson+",\"ipAllowlist\":"+k.ipAllowlistJson+",\"quota\":"+k.quota+",\"status\":\""+k.status+"\",\"expiresAt\":"+(k.expiresAt==null?"null":"\""+k.expiresAt+"\"")+"}";if(k.expiresAt==null){redis.opsForValue().set(key(k.keyHash),v);}else{Duration ttl=Duration.between(Instant.now(),k.expiresAt);if(!ttl.isNegative()&&!ttl.isZero())redis.opsForValue().set(key(k.keyHash),v,ttl);}}catch(RuntimeException e){log.warn("Unable to synchronize API key to Redis",e);}}public void remove(String hash){try{redis.delete(key(hash));}catch(RuntimeException e){log.warn("Unable to remove API key from Redis",e);}}private String key(String h){return "api-key:"+h;}}